 err=max(abs(a-b) for a,b in zip(x['samples'],samples));c=max(abs(x['checksums'][b][j]-bins[b][j])/((ch*n+15-b)//16) for b in range(16) for j in range(2));assert err<=2e-5 and c<=6e-5
